      check("hoppers.a-super-hopper-feeds-a-furnace-through-the-right-slot", () -> {
         // A furnace is not a chest with three slots: the top face feeds the input, the side feeds
         // the fuel, and the output is nobody's to fill. A hopper that fills "the first slot with
         // room" pours ore into the fuel slot and coal into the input - and a Super Smelter fed
         // that way is a machine that never gets the item it needs in the slot it needs it in.
         ServerLevel level = server.overworld();
         BlockPos pos = new BlockPos(168, 300, 168);
         BlockPos below = pos.below();
         BlockPos sidePos = new BlockPos(184, 300, 184);
         BlockPos west = sidePos.west();
         ServerPlayer probe = FakePlayer.get(level, ownProfile("super-hopper-smelt"));
         String key = MachineManager.keyFor(level, pos);
         String sideKey = MachineManager.keyFor(level, sidePos);
         try {
            // From above: the ore belongs in the input and nowhere else.
            level.setBlock(pos, Blocks.HOPPER.defaultBlockState(), 3);
            level.setBlock(below, Blocks.FURNACE.defaultBlockState(), 3);
            MachineManager.all().put(
               key, new MachineManager.Machine(MachineManager.TYPE_SUPER_HOPPER, probe.getUUID(), "probe", 0L, new long[4], true)
            );
            net.minecraft.world.Container topHopper = (net.minecraft.world.Container)level.getBlockEntity(pos);
            net.minecraft.world.Container topFurnace = (net.minecraft.world.Container)level.getBlockEntity(below);
            topHopper.setItem(0, new ItemStack(Items.RAW_IRON, 3));
            com.fortuneandfavors.economy.HeavyHoppers.tickSuperHopper(level, pos);
            require(
               topFurnace.getItem(0).getItem() == Items.RAW_IRON && topFurnace.getItem(0).getCount() == 3,
               "a super hopper above a furnace did not fill the input: " + topFurnace.getItem(0)
            );
            require(
               topFurnace.getItem(2).isEmpty(),
               "a super hopper fed a furnace's output slot, where the item is never smelted: " + topFurnace.getItem(2)
            );
            // From the side: the coal belongs in the fuel slot, not the input.
            level.setBlock(
               sidePos,
               Blocks.HOPPER.defaultBlockState().setValue(net.minecraft.world.level.block.HopperBlock.FACING, Direction.WEST),
               3
            );
            level.setBlock(west, Blocks.FURNACE.defaultBlockState(), 3);
            MachineManager.all().put(
               sideKey, new MachineManager.Machine(MachineManager.TYPE_SUPER_HOPPER, probe.getUUID(), "probe", 0L, new long[4], true)
            );
            net.minecraft.world.Container sideHopper = (net.minecraft.world.Container)level.getBlockEntity(sidePos);
            net.minecraft.world.Container sideFurnace = (net.minecraft.world.Container)level.getBlockEntity(west);
            sideHopper.setItem(0, new ItemStack(Items.COAL, 4));
            com.fortuneandfavors.economy.HeavyHoppers.tickSuperHopper(level, sidePos);
            require(
               sideFurnace.getItem(1).getItem() == Items.COAL && sideFurnace.getItem(1).getCount() == 4,
               "a super hopper beside a furnace did not fill the fuel slot: fuel=" + sideFurnace.getItem(1)
                  + " input=" + sideFurnace.getItem(0) + " out=" + sideFurnace.getItem(2)
                  + " hopper=" + sideHopper.getItem(0)
                  + " state=" + level.getBlockState(sidePos)
            );
            require(
               sideFurnace.getItem(0).isEmpty(),
               "a super hopper put the fuel in the input slot: " + sideFurnace.getItem(0)
            );
         } finally {
            cleanupBlocks(level, List.of(pos, below, sidePos, west));
            MachineManager.all().remove(key);
            MachineManager.all().remove(sideKey);
         }
      });

