            net.minecraft.server.level.ServerBossEvent bar = com.fortuneandfavors.economy.BossManager.bossBarForTest(warden);
            require(bar != null, "the Elder Warden's fight has no health bar at all");
            com.fortuneandfavors.economy.BossManager.plantRiggingForTest(id);

