            require(warden.isRemoved() || !warden.isAlive(), "a server stop left the boss standing in the world");
            require(!com.fortuneandfavors.economy.BossManager.hasFightForTest(id), "a server stop left the fight registered");
            require(!bar.isVisible(), "a server stop left a boss bar on the screen");
            require(
               !com.fortuneandfavors.economy.BossManager.leftoversForTest(id),
               "a server stop left the boss's rigging in the world, which is the orphaned-statue bug"
            );
